<?php
if (!defined('ABSPATH')) exit;
function gim_propose_additional_work($job_id,$provider_user_id,$reason,$items){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||$job->status!=='in_progress'||!gim_job_owned_by_provider($job,$provider_user_id))return new WP_Error('forbidden','Additional work is only available on your in-progress job.'); $open=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".gim_table('additional_work')." WHERE job_id=%d AND status IN ('proposed','customer_approved','payment_pending')",$job_id)); if($open)return new WP_Error('open','Resolve the existing additional-work request first.'); $n=gim_normalize_estimate_items($items); if($n['service']<=0)return new WP_Error('amount','Additional service amount required.'); $p=gim_provider_profile($provider_user_id); $ref=gim_ref('GM-AW'); $digest=hash('sha256',gim_json([$job_id,$p->id,$reason,$n])); $wpdb->insert(gim_table('additional_work'),['reference'=>$ref,'job_id'=>$job_id,'provider_id'=>$p->id,'status'=>'proposed','reason'=>sanitize_textarea_field($reason),'items_json'=>gim_json($n['items']),'service_pence'=>$n['service'],'materials_pence'=>$n['materials'],'digest'=>$digest,'created_at'=>gim_now()]); gim_audit('additional_work.proposed','additional_work',$ref); return $wpdb->insert_id; }
function gim_customer_decide_additional_work($id,$customer_id,$decision){ global $wpdb; $aw=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('additional_work').' WHERE id=%d',$id)); if(!$aw||$aw->status!=='proposed')return new WP_Error('request','Request unavailable.'); $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$aw->job_id)); if(!$job||!gim_job_owned_by_customer($job,$customer_id))return new WP_Error('forbidden','Forbidden.'); if($decision==='approve')$status='customer_approved'; elseif($decision==='reject')$status='customer_rejected'; else return new WP_Error('decision','Invalid decision.'); $wpdb->update(gim_table('additional_work'),['status'=>$status,'decided_at'=>gim_now()],['id'=>$id]); gim_audit('additional_work.'.$decision.'d','additional_work',$aw->reference); return true; }
function gim_extra_work_authorized($job_id){ global $wpdb; $n=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".gim_table('additional_work')." WHERE job_id=%d AND status IN ('proposed','customer_approved','payment_pending')",$job_id)); return (int)$n===0; }
